const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '3:1' }];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var payload = '3:1';
    var fs = Math.max(14, Math.round(Math.min(W, H) * 0.105));
    var m = (metrics && metrics[0]) || null;
    var tw = null, th = null;
    var cands = m ? [m, m.measured, m.size, m.metrics, m.dims] : [];
    for (var i = 0; i < cands.length; i++) {
      var c = cands[i];
      if (!c || typeof c !== 'object') continue;
      if (tw === null) {
        if (typeof c.width === 'number') tw = c.width;
        else if (typeof c.w === 'number') tw = c.w;
      }
      if (th === null) {
        if (typeof c.height === 'number') th = c.height;
        else if (typeof c.h === 'number') th = c.h;
      }
    }
    if (tw === null) tw = payload.length * fs * 0.6;
    if (th === null) th = fs;

    var padX = Math.max(44, Math.round(W * 0.13));
    var x0 = padX;
    var x1 = Math.round(W - padX);
    var L = x1 - x0;
    var y = Math.round(H * 0.42);
    var xd = Math.round(x0 + L * 0.75);

    var capHalf = Math.max(8, Math.round(Math.min(W, H) * 0.05));
    var tickHalf = Math.max(5, Math.round(capHalf * 0.6));

    var main = visualSdk.polyline([[x0, y], [x1, y]]);
    var capLeft = visualSdk.polyline([[x0, y - capHalf], [x0, y + capHalf]]);
    var capRight = visualSdk.polyline([[x1, y - capHalf], [x1, y + capHalf]]);
    var divider = visualSdk.polyline([[xd, y - capHalf], [xd, y + capHalf]]);
    var ux1 = Math.round(x0 + L * 0.25);
    var ux2 = Math.round(x0 + L * 0.5);
    var unit1 = visualSdk.polyline([[ux1, y - tickHalf], [ux1, y + tickHalf]]);
    var unit2 = visualSdk.polyline([[ux2, y - tickHalf], [ux2, y + tickHalf]]);
    var dot = visualSdk.circle(xd, y, Math.max(3, Math.round(capHalf * 0.38)));

    var brY = y + Math.max(26, Math.round(capHalf * 2.4));
    var brEnd = Math.max(6, Math.round(capHalf * 0.8));
    var bracket = visualSdk.polyline([[x0, brY - brEnd], [x0, brY], [x1, brY], [x1, brY - brEnd]]);

    var labelY = brY + Math.max(10, Math.round(th * 0.55));

    return {
      schemaVersion: 1,
      sceneId: 'ratio-3-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'seg-main', commands: main },
        { id: 'seg-capL', commands: capLeft },
        { id: 'seg-capR', commands: capRight },
        { id: 'seg-div', commands: divider },
        { id: 'seg-u1', commands: unit1 },
        { id: 'seg-u2', commands: unit2 },
        { id: 'seg-dot', commands: dot },
        { id: 'seg-bracket', commands: bracket }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'seg-main', stroke: '#26354a', strokeWidth: 3 },
          { type: 'path', pathId: 'seg-capL', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'seg-capR', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'seg-div', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'seg-u1', stroke: '#8a98aa', strokeWidth: 1.5 },
          { type: 'path', pathId: 'seg-u2', stroke: '#8a98aa', strokeWidth: 1.5 },
          { type: 'path', pathId: 'seg-dot', fill: '#26354a', stroke: '#26354a' },
          { type: 'path', pathId: 'seg-bracket', stroke: '#26354a', strokeWidth: 1.5 },
          { type: 'label', text: payload, x: Math.round((x0 + x1) / 2), y: Math.round(labelY), fontSize: fs, textAnchor: 'middle', dominantBaseline: 'middle', fill: '#26354a' }
        ]
      }
    };
  }
};
